// th18_s3_b4: TH18 v1.00a Stage 3 BossCard2, st03bs.ecl.txt:623-783.
// Source spell declaration 653/655; source attack clock t0 = spell start,
// first async batch at source t90.  Control enemy at (0,0) owns the phase;
// the real boss at source (0,128) keeps the source hitbox/hurtbox and body.
const TIME_LIMIT: int = 2522; // 120 opening buffer + 2400 source timeout + 2 tail
const SOURCE_LIMIT: int = 2400;
const TH18_RICE: int = 480;
const TH18_BALL2: int = 432;

// type 0x200000 VELTIME (TH18: a = ramp frames, r = target scalar speed,
// s <= -999990 keeps the bullet's current angle).  The source ramps the
// scalar speed while the direction stays fixed, so a constant cartesian
// acceleration along the spawn direction is the same path.
xformdef DECEL(target: fx, frames: int) {
    set_gravity(at_spawn((target - $self_speed) / (frames as fx) * cos($self_angle)),
                at_spawn((target - $self_speed) / (frames as fx) * sin($self_angle)));
    wait(frames);
    set_gravity(0fx, 0fx);
}

// st03bs.ecl.txt:695-737 BossCard2_at2a.  Hard/Lunatic only.
// etAim 3 = fixed-direction ring; with M=1 the second etAngle parameter is
// unused, so the ring base is the full-circle RANDRAD sample.
async sub rice_ring() {
    var rank: int = global(GVAR_RANK);
    var n: int = 96;          // E/N 96, H 80, L 96
    var gap: int = 120;       // E/N/H 120, L 90
    if rank == 2 { n = 80; }
    if rank == 3 { gap = 90; }

    wait(200);                // source wait(200) before the first ring
    sh_reset(0);
    sh_sprite(0, TH18_RICE, 10);      // etSprite(0,8,10)
    sh_aim(0, 0);                     // etAim(0,3)
    sh_ring(0, 1);
    sh_count(0, n, 1);
    sh_speed(0, 3fx, 0fx);
    sh_dist(0, -12fx);                // ANIM a=1: position -= 4 * 3.0 speed
    sh_xform(0, DECEL(0.8fx, 100));   // etEx 0x200000 a100 r0.8 s=-1000000
    loop {
        var base: angle = (rand(65536)) as angle; // %RANDRAD full circle
        sh_angle(0, base, 0deg);
        sh_fire(0);
        wait(gap);
    }
}

// st03bs.ecl.txt:738-783 BossCard2_at2b.  The laser EX index 0 SHOOTPREP
// (mode 8, start index 8) makes the Line fire one bullet every 2 frames
// (E: 4), and the child bullets run records 8+ : ANIM a=1, BRIGHT, VELTIME.
async sub laser_shots(x: fx, y: fx, interval: int, shots: int) {
    for i in 0..shots {
        var a: angle = (rand(65536)) as angle; // mode 8 angle first; r=-pi,s=pi is full circle
        var rv: int = rand(65536);             // mode 8 speed second: 2.3 + U*1.0
        var u: fx = (rv - 32768) as fx / 65536 + 0.5fx;
        var speed: fx = 2.3fx + u;
        // ANIM a=1 retreats four times the spawn velocity.
        var sx: fx = x - 4fx * speed * cos(a);
        var sy: fx = y - 4fx * speed * sin(a);
        _ = fire(TH18_BALL2, 6, sx, sy, speed, a, DECEL(0.4fx, 90), none);
        wait(interval);
    }
}

async sub laser_burst() {
    var b: angle = aim_player() - 180deg; // %ANGLE_PLAYER - pi, read once
    var x: fx = $self_x;
    var y: fx = $self_y - 40fx;           // etOffset(1,0,-40)
    var rank: int = global(GVAR_RANK);
    var interval: int = 2;                // WAIT a=2 on N/H/L
    if rank == 0 { interval = 4; }        // WAIT a=4 on E
    var shots: int = 15;
    if rank == 0 { shots = 8; }

    // laserNew(1,0,256,0,16): Line, judgment segment 0.1L..0.9L, w=16 -> target width 8.
    for k in 0..5 {
        var h: int = laser(6, x, y, b, 230.4fx, 8fx, 0, 30, 0);
        lz_start(h, 25.6fx);
        spawn laser_shots(x, y, interval, shots);
        b = b + 72deg;                    // 1.256637f
    }
    wait(30);
}

// --- moveRand(60,4,0.7) with moveLimit(0,128,96,64) -----------------------
// Source final-position clamp is x[-48,48], y[96,160]; the direction choice
// inner box is x[-24,24], y[112,144].  Same recipe as the verified Stage 1
// moveRand helper, with the 0.7 start speed and this segment's limits.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = ((60-k) as fx) * 0.7fx / 60fx; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -48fx { nx = -48fx; }
    if nx > 48fx { nx = 48fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    // Source 0x405b90: signed unit random * pi; values below are unwrapped BAM.
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -24fx {
        a = r/3;
    } else if $self_x > 24fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad (nearest BAM bounds).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// st03bs.ecl.txt:623-693 BossCard2.
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);   // source setHitbox(48,48)
    set_hurtbox(20fx);  // source setHurtbox(40,40)
    set_self_int(0, 0);
    set_self_int(1, $frame+SOURCE_LIMIT); // source timeout boundary
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);

    wait(90);                             // source +90 label
    if global(GVAR_RANK) >= 2 { spawn rice_ring(); }
    while $frame < self_int(1) {
        // $E=3: three BossCard2_at2b batches, then wait(200) and restart.
        for e in 0..3 {
            spawn laser_burst();          // @BossCard2_at2b(0.7853982f) async
            card_wait(30);
            if $frame >= self_int(1) { return; }
            card_move_rand();             // moveRand(60,4,0.7)
            card_wait(60);
            if $frame >= self_int(1) { return; }
        }
        card_wait(200);
    }
    return;
}

// --- training shell -------------------------------------------------------
async sub pattern_hold() {
    wait(120);                            // opening buffer; no bullets
    _ = spawn_enemy(0fx, 128fx, 2400, 0, 0, 0, boss_main);
    loop { wait(600); }
}

async sub encounter() {
    set_enemy_flag(ENEMY_NO_BODY, 1);      // control enemy at (0,0) never body-collides
    set_invuln(65535);
    spell_begin(0, 24, pattern_hold, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, encounter);
    loop { wait(600); }
}
